import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String groupBy = req.getParameter("group_by");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "returns");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Template-based query construction
        String templateKey = "report." + reportType + ".query";
        String queryTemplate = loadQueryTemplate(templateKey);

        // The group_by parameter is inserted into ORDER BY clause
        // Developer assumed frontend dropdown limits values
        Map<String, String> params = new HashMap<>();
        params.put("date_from", dateFrom);
        params.put("date_to", dateTo);
        params.put("group_by", groupBy != null ? groupBy : "created_date");

        StringSubstitutor sub = new StringSubstitutor(params);
        String finalQuery = sub.replace(queryTemplate);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(30);

            ResultSet rs = stmt.executeQuery(finalQuery);
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String loadQueryTemplate(String key) {
        // Templates stored in properties file on classpath
        // Example: SELECT product_id, SUM(amount) as total FROM sales 
        //          WHERE sale_date BETWEEN '${date_from}' AND '${date_to}' 
        //          GROUP BY ${group_by} ORDER BY ${group_by}
        Properties props = new Properties();
        try (InputStream is = getClass().getResourceAsStream("/queries.properties")) {
            props.load(is);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load query templates", e);
        }
        return props.getProperty(key, "");
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        List<Map<String, Object>> rows = new ArrayList<>();
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        while (rs.next()) {
            Map<String, Object> row = new LinkedHashMap<>();
            for (int i = 1; i <= cols; i++) {
                row.put(meta.getColumnLabel(i), rs.getObject(i));
            }
            rows.add(row);
        }
        // Simple JSON serialization
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < rows.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append("{");
            int j = 0;
            for (Map.Entry<String, Object> e : rows.get(i).entrySet()) {
                if (j++ > 0) sb.append(",");
                sb.append("\"").append(e.getKey()).append("\":");
                if (e.getValue() instanceof Number) {
                    sb.append(e.getValue());
                } else {
                    sb.append("\"").append(String.valueOf(e.getValue())
                        .replace("\"", "\\\"")).append("\"");
                }
            }
            sb.append("}");
        }
        sb.append("]");
        return sb.toString();
    }
}
